struct Version: Comparable {
    var major: Int
    var minor: Int
    // == and != are synthesised member-wise; only '<' is required by the protocol
    static func < (lhs: Version, rhs: Version) -> Bool {
        (lhs.major, lhs.minor) < (rhs.major, rhs.minor)
    }
}
// <=, >, >= come from the standard library's Comparable extension

enum Priority: Comparable { case low, medium, high }   // ordering synthesised from case order
